// camelise() camel-cases the input string
function camelise(str) {
    return str.replaceAll("-", "").replaceAll(" ", "").replaceAll("_", "").replace(/(?:^\w|[A-Z]|\b\w)/g, function(word, index) {
        return index === 0 ? word.toLowerCase() : word.toUpperCase();
    }).replace(/\s+/g, '');
}
// offCanvasMeta() adds event listeners for updating theme-color meta when offcanvases are opened
function offCanvasMeta(el) {
    var meta = document.querySelector("meta[name='theme-color']");
    const metaColour = meta.content;
    console.log(el);
    console.log(el.children[0]);
    el.children[0].children[0].addEventListener("toggle", (e)=>{
        e.newState === "open" ? meta.content = "rgb(15,15,15)" : meta.content = metaColour;
    });
}
